# qx_partition :: ([1, 2, 3, 4, 5], 'x % 2 == 0')
def qx_partition(xs, pred_src):
    pred = eval('lambda x: ' + pred_src)
    yes, no = [], []
    for x in xs: (yes if pred(x) else no).append(x)
    return yes, no

if __name__ == '__main__':
    print(qx_partition(([1, 2, 3, 4, 5], 'x % 2 == 0')))

